import {geometryPath} from './cartography.js';
import {symbolFor} from './place-icons.js';
export class OverviewMap{
 constructor(canvas,world,onSelect){this.canvas=canvas;this.world=world;this.onSelect=onSelect;this.zoom=1;this.pan=[0,0];this.pointers=new Map();this.dragged=false;this.resize=new ResizeObserver(()=>this.draw());this.resize.observe(canvas);this.bind();this.draw();}
 dimensions(){const c=this.canvas,w=this.world;this.base=Math.min((c.width-40)/w.max[0],(c.height-40)/w.max[1]);this.scale=this.base*this.zoom;this.offset=[c.width/2-w.max[0]*this.scale/2+this.pan[0],c.height/2-w.max[1]*this.scale/2+this.pan[1]];}
 point(p){return[p[0]*this.scale+this.offset[0],p[1]*this.scale+this.offset[1]];}
 inverse(p){return[(p[0]-this.offset[0])/this.scale,(p[1]-this.offset[1])/this.scale];}
 limit(){const c=this.canvas,w=this.world;this.pan=this.pan.map((v,i)=>Math.max(-w.max[i]*this.scale/2,Math.min(w.max[i]*this.scale/2,v)));}
 zoomBy(factor,anchor=[this.canvas.width/2,this.canvas.height/2]){this.dimensions();const before=this.inverse(anchor);this.zoom=Math.max(1,Math.min(10,this.zoom*factor));this.dimensions();const after=this.point(before);this.pan=this.pan.map((v,i)=>v+anchor[i]-after[i]);this.limit();this.draw();}
 reset(){this.zoom=1;this.pan=[0,0];this.draw();}
 draw(){const c=this.canvas,w=this.world,r=c.getBoundingClientRect(),dpr=Math.min(globalThis.devicePixelRatio||1,1.5);if(r.width&&r.height&&(c.width!==Math.round(r.width*dpr)||c.height!==Math.round(r.height*dpr))){const ratio=Math.round(r.width*dpr)/c.width;this.pan=this.pan.map(v=>v*ratio);c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);}this.dimensions();const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.fillStyle='#86b9bd';g.fillRect(0,0,c.width,c.height);const origin=this.point([0,0]);if(w.cartography.image.naturalWidth)g.drawImage(w.cartography.image,...origin,w.max[0]*this.scale,w.max[1]*this.scale);
 const a=this.inverse([0,0]),b=this.inverse([c.width,c.height]);if(this.zoom>=2){const fs=w.cartography.index.query([...a,...b]);for(const f of fs.filter(f=>f.tags.highway||f.tags.railway==='rail')){g.beginPath();f.points.forEach((p,i)=>i?g.lineTo(...this.point(p)):g.moveTo(...this.point(p)));g.strokeStyle=f.tags.railway?'#555e69':'#fff7dd';g.lineWidth=f.tags.railway?1.5:Math.max(1,w.cartography.width(f)*this.scale);g.stroke();}}
 for(const d of w.data.districts.filter(d=>d.county==='홍성군')){geometryPath(g,d.geometry,p=>this.point(w.project(p)));g.strokeStyle='#436a54';g.lineWidth=1;g.setLineDash([5,4]);g.stroke();g.setLineDash([]);const pos=this.point(w.project(d.center));g.font='700 15px NanumRound,sans-serif';g.textAlign='center';g.strokeStyle='#fff8e6';g.lineWidth=3;g.strokeText(d.name,...pos);g.fillStyle='#325540';g.fillText(d.name,...pos);}
 this.pins=[];for(const p of w.places){const[x,y]=this.point(p.point);if(x<0||y<0||x>c.width||y>c.height)continue;const s=symbolFor(p);g.beginPath();g.arc(x,y,7,0,Math.PI*2);g.fillStyle=s.color;g.fill();g.strokeStyle='#fff9e5';g.lineWidth=1.5;g.stroke();if(this.zoom>=2.5){g.font='700 14px NanumRound,sans-serif';g.textAlign='left';g.strokeStyle='#fff9e8';g.lineWidth=4;g.strokeText(p.short,x+10,y+5);g.fillStyle='#244b38';g.fillText(p.short,x+10,y+5);}this.pins.push({p,x,y});}
 const me=this.point(w.position);g.beginPath();g.arc(...me,10,0,Math.PI*2);g.fillStyle='#fff';g.fill();g.beginPath();g.arc(...me,6,0,Math.PI*2);g.fillStyle='#e86a35';g.fill();const label=document.querySelector('#overview-zoom-label');if(label)label.textContent=Math.round(this.zoom*100)+'%';}
 coords(e){const r=this.canvas.getBoundingClientRect();return[(e.clientX-r.left)*this.canvas.width/r.width,(e.clientY-r.top)*this.canvas.height/r.height];}
 bind(){const c=this.canvas;c.addEventListener('wheel',e=>{e.preventDefault();this.zoomBy(e.deltaY<0?1.2:1/1.2,this.coords(e));},{passive:false});c.addEventListener('pointerdown',e=>{c.setPointerCapture(e.pointerId);const p=this.coords(e);this.pointers.set(e.pointerId,p);this.start=p;this.dragged=this.pointers.size>1;});c.addEventListener('pointermove',e=>{if(!this.pointers.has(e.pointerId))return;const old=[...this.pointers.values()],before=this.pointers.get(e.pointerId),p=this.coords(e);this.pointers.set(e.pointerId,p);if(Math.hypot(p[0]-this.start[0],p[1]-this.start[1])>8)this.dragged=true;if(this.pointers.size===2){this.dragged=true;const next=[...this.pointers.values()],d=Math.hypot(old[0][0]-old[1][0],old[0][1]-old[1][1]),n=Math.hypot(next[0][0]-next[1][0],next[0][1]-next[1][1]);if(d>5)this.zoomBy(n/d,[(next[0][0]+next[1][0])/2,(next[0][1]+next[1][1])/2]);}else{this.pan[0]+=p[0]-before[0];this.pan[1]+=p[1]-before[1];this.limit();this.draw();}});c.addEventListener('pointerup',e=>{const p=this.coords(e),click=!this.dragged&&this.pointers.size===1;this.pointers.delete(e.pointerId);if(click){const hits=this.pins.filter(v=>Math.hypot(v.x-p[0],v.y-p[1])<16).map(v=>v.p);if(hits.length)this.onSelect(hits);}});const cancel=e=>{this.pointers.delete(e.pointerId);this.dragged=true;};c.addEventListener('pointercancel',cancel);c.addEventListener('lostpointercapture',cancel);}
 destroy(){this.resize.disconnect();}
}
